"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83256"],{70644(e){e.exports=JSON.parse('{"id":"FIN-911","slug":"mortgage-backed-security","term":"Mortgage-Backed Security (MBS)","also_known_as":["MBS"],"difficulty":"Intermediate","definition":"A mortgage-backed security (MBS) is an investment backed by a pool of home or commercial mortgages, which pays investors from the interest and principal repayments made by the borrowers.","explanation":["MBS are created through securitization. Lenders pool many mortgages together and sell them to an entity that issues securities. As homeowners make their monthly payments, the money flows through to investors.","In the United States, a large part of the MBS market is made up of securities issued or guaranteed by government-sponsored enterprises, Fannie Mae and Freddie Mac, and by the government agency Ginnie Mae. These carry little credit risk because of the guarantees. Other MBS, called private-label or non-agency MBS, are issued by banks and other firms without such guarantees.","For example, a pension fund might buy agency MBS to earn a slightly higher yield than government bonds while taking little credit risk.","MBS carry a distinctive risk called prepayment risk. When interest rates fall, many homeowners refinance and repay their mortgages early, so investors get their money back sooner than expected and must reinvest at lower rates. When rates rise, prepayments slow, extending the security\'s life. In the years before 2008, MBS backed by risky subprime mortgages suffered heavy losses when borrowers defaulted, contributing to the financial crisis."],"note":"","total":1500,"prev":{"slug":"mortgage","term":"Mortgage"},"next":{"slug":"mortgage-insurance","term":"Mortgage Insurance"}}')}}]);